增删改查增删改查
String-字符串类型123456789101112131415161718192021222324252627282930313233343536373839404142package com.tensquare.article;import com.tensquare.article.pojo.User;import org.junit.Test;import org.junit.runner.RunWith;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.data.redis.core.RedisTemplate;import org.springframework.test.context.junit4.SpringJUnit4ClassRunner;import java.util.concurrent.TimeUnit;@SpringBootTest@RunWith(SpringJUnit4ClassRunner.class)public class RedisTemTest &#123;    @Autowired    private RedisTemplate redisTemplate;    /*     * String类型的数据增删改查     * */    @Test    public void StringDataTest() &#123;        // 创建User对象 ,要存入String类型的对象,需要实现 Serializable 接口        User user = new User(&quot;1&quot;, &quot;Tom&quot;, &quot;打棒球&quot;, 15);        // 添加数据        redisTemplate.opsForValue().set(&quot;user&quot;, user);        // 添加数据并设置有效时间为30s, (30, TimeUnit.SECONDS) 分别代表数字,计量单位        redisTemplate.opsForValue().set(&quot;user1&quot;, &quot;Rose&quot;, 30, TimeUnit.SECONDS);        //查找数据 根据key获取value        User value = (User) redisTemplate.opsForValue().get(&quot;user&quot;);        //查找数据 长度        Long size = redisTemplate.opsForValue().size(&quot;user1&quot;);        // 删除数据        redisTemplate.delete(&quot;user1&quot;);    &#125;&#125;

Set-集合类型1234567891011121314151617181920212223242526272829303132333435363738394041424344454647/*    * Set 集合类型CURD    * */   @Test   public void SetDataTest() &#123;       User user = new User(&quot;1&quot;, &quot;Tom&quot;, &quot;打棒球&quot;, 15);       User user1 = new User(&quot;2&quot;, &quot;Jack&quot;, &quot;打网球&quot;, 17);       User user2 = new User(&quot;3&quot;, &quot;Rose&quot;, &quot;打篮球&quot;, 18);       User user3 = new User(&quot;4&quot;, &quot;Jerry&quot;, &quot;踢足球&quot;, 19);       // 添加 key为user_1的user对象       redisTemplate.opsForSet().add(&quot;user_1&quot;, user);       redisTemplate.opsForSet().add(&quot;user_1&quot;, user1);	// 定时 设置 user_1 数据的存活时间为5秒 测试时注释       redisTemplate.expire(&quot;user_1&quot;, 5, TimeUnit.SECONDS);       // 查询 user_1 集合中的所有 value       Set user1_list = redisTemplate.opsForSet().members(&quot;user_1&quot;);       // 查询 user_1 集合中是否有 user 对象       Boolean result = redisTemplate.opsForSet().isMember(&quot;user_1&quot;, user);       // 删除 user_1 集合中的 user对象 ,并返回移除成功数量       Long success_count = redisTemplate.opsForSet().remove(&quot;user_1&quot;, user);       // 删除 user_1 集合中的栈顶元素       Object user_1 = redisTemplate.opsForSet().pop(&quot;user_1&quot;);       // 测试 交集 并集 差集的数据       redisTemplate.opsForSet().add(&quot;names1&quot;, user, user1, user2);       redisTemplate.opsForSet().add(&quot;names2&quot;, user, user1, user3);       //取交集       Set&lt;User&gt; intersect = redisTemplate.opsForSet().intersect(&quot;names1&quot;, &quot;names2&quot;);       for (User u1 : intersect) &#123;           System.out.println(&quot;交集: &quot; + u1);       &#125;       //取并集       Set&lt;User&gt; union = redisTemplate.opsForSet().union(&quot;names1&quot;, &quot;names2&quot;);       for (User u2 : union) &#123;           System.out.println(&quot;并集: &quot; + u2);       &#125;       //取差集[第一个集合中存在，但第二个集合中不存在的元素]       Set&lt;User&gt; difference = redisTemplate.opsForSet().difference(&quot;names1&quot;, &quot;names2&quot;);       for (User u3 : difference) &#123;           System.out.println(&quot;差集: &quot; + u3);       &#125;   &#125;

List-链表类型123456789101112131415161718192021222324252627282930313233343536373839404142/*    * List 数据类型的CRUD    * */   @Test   public void ListDataTest() &#123;       User user = new User(&quot;1&quot;, &quot;Tom&quot;, &quot;打棒球&quot;, 15);       User user1 = new User(&quot;2&quot;, &quot;Jack&quot;, &quot;打网球&quot;, 17);       //从左边添加一个元素       redisTemplate.opsForList().rightPush(&quot;user1&quot;, user);       //从左边添加多个元素       redisTemplate.opsForList().leftPushAll(&quot;user2&quot;, user, user1);       //从右边添加一个元素       redisTemplate.opsForList().rightPush(&quot;user3&quot;, user1);       //从右边添加多个元素       redisTemplate.opsForList().rightPushAll(&quot;user4&quot;, user, user1);	// 定时 设置 user2 数据的存活时间为5秒 测试时注释       redisTemplate.expire(&quot;user2&quot;, 5, TimeUnit.SECONDS);       /* 根据key和元素索引进行查询        *  0和正数代表从左边开始        *  负数代表从右边开始        * */       // 查询 user3 链表中所有的元素       List user3 = redisTemplate.opsForList().range(&quot;user3&quot;, 0, -1);       // 查询 user3 链表中第一个元素       User data = (User) redisTemplate.opsForList().index(&quot;user3&quot;, 0);       System.out.println(data);       // 修改 user3 链表中第一个的元素为 user1 对象       redisTemplate.opsForList().set(&quot;user3&quot;, 0, user); 	   	    // 删除链表左侧第二个 user 对象       redisTemplate.opsForList().remove(&quot;user3&quot;, 2, user);       //删除 user3 链表中左侧的第一个元素       redisTemplate.opsForList().leftPop(&quot;user3&quot;);       //删除 user3 链表中右侧的第一个元素       redisTemplate.opsForList().rightPop(&quot;user3&quot;);   &#125;

