;    &#125;     /**     * 获取 key 下的 所有 hashkey 字段     *     * @param key     * @return     */    public Set&lt;Object&gt; hashKeys(String key) &#123;        return redisTemplate.opsForHash().keys(key);    &#125;     /**     * 获取指定 hash 下面的 键值对 数量     *     * @param key     * @return     */    public Long hashSize(String key) &#123;        return redisTemplate.opsForHash().size(key);    &#125;     //- - - - - - - - - - - - - - - - - - - - -  list类型 - - - - - - - - - - - - - - - - - - - -     /**     * 在变量左边添加元素值     *     * @param key     * @param value     * @return     */    public void leftPush(String key, Object value) &#123;        redisTemplate.opsForList().leftPush(key, value);    &#125;     /**     * 获取集合指定位置的值。     *     * @param key     * @param index     * @return     */    public Object index(String key, long index) &#123;        return redisTemplate.opsForList().index(&quot;list&quot;, 1);    &#125;     /**     * 获取指定区间的值。     *     * @param key     * @param start     * @param end     * @return     */    public List&lt;Object&gt; range(String key, long start, long end) &#123;        return redisTemplate.opsForList().range(key, start, end);    &#125;     /**     * 把最后一个参数值放到指定集合的第一个出现中间参数的前面，     * 如果中间参数值存在的话。     *     * @param key     * @param pivot     * @param value     * @return     */    public void leftPush(String key, String pivot, String value) &#123;        redisTemplate.opsForList().leftPush(key, pivot, value);    &#125;     /**     * 向左边批量添加参数元素。     *     * @param key     * @param values     * @return     */    public void leftPushAll(String key, String... values) &#123;//        redisTemplate.opsForList().leftPushAll(key,&quot;w&quot;,&quot;x&quot;,&quot;y&quot;);        redisTemplate.opsForList().leftPushAll(key, values);    &#125;     /**     * 向集合最右边添加元素。     *     * @param key     * @param value     * @return     */    public void leftPushAll(String key, String value) &#123;        redisTemplate.opsForList().rightPush(key, value);    &#